// personaActivateVals returns a JSON string of {"active_persona":"<name>"} suitable for hx-vals.
func personaActivateVals(name string) string {
	b, err := json.Marshal(map[string]string{"active_persona": name})
	if err != nil {
		return `{"active_persona":""}`
	}
	return string(b)
}

// previewPrompt returns the first 120 characters or the full prompt if shorter.
func previewPrompt(prompt string) string {
	if prompt == "" {
		return "(no custom prompt — uses default)"
	}
	maxLen := 120
	runes := []rune(prompt)
	if len(runes) <= maxLen {
		return prompt
	}
	return string(runes[:maxLen]) + "…"
}

// promptOrDefault returns the user's prompt, or the canonical default prompt
// (persona.DefaultPrompt) when the user's prompt is empty/blank. New-persona and
// empty-prompt edit forms pre-fill this as an editable starting point so a user
// specialising a persona does not silently lose the concise/reasoning guardrails
// (issue #1140). The value is always freely editable and stays empty-blank if the
// user clears it.
func promptOrDefault(prompt string) string {
	if strings.TrimSpace(prompt) == "" {
		return persona.DefaultPrompt
	}
	return prompt
}

// isSkillSelected returns true if the given skill name is in the selected list.
func isSkillSelected(selected []string, name string) bool {
	for _, s := range selected {
		if s == name {
			return true
		}
	}
	return false
}

